SELECT COUNT(*) AS total_rows, COUNT(salary) AS known_salaries,
       COUNT(DISTINCT salary) AS distinct_salaries
FROM employees;

SELECT employee_id, salary FROM employees
WHERE salary IS NOT NULL
ORDER BY salary DESC, employee_id ASC LIMIT 3;

SELECT o.order_id, c.name, o.amount
FROM orders o JOIN customers c ON c.customer_id = o.customer_id
WHERE o.status = 'paid' ORDER BY o.order_id;

SELECT e.employee_id, e.salary FROM employees e
WHERE e.salary > (SELECT AVG(x.salary) FROM employees x WHERE x.dept=e.dept)
ORDER BY e.employee_id;

WITH i AS (
 SELECT order_id, SUM(amount) AS item_total FROM items GROUP BY order_id
), p AS (
 SELECT order_id, SUM(amount) AS payment_total FROM payments GROUP BY order_id
)
SELECT o.order_id, COALESCE(i.item_total,0) AS item_total,
 COALESCE(p.payment_total,0) AS payment_total
FROM orders o LEFT JOIN i ON i.order_id=o.order_id
LEFT JOIN p ON p.order_id=o.order_id
WHERE o.order_id IN (101,102) ORDER BY o.order_id;

SELECT p.payment_id, p.order_id FROM payments p
LEFT JOIN orders o ON o.order_id=p.order_id
WHERE o.order_id IS NULL ORDER BY p.payment_id;

WITH r AS (
 SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS salary_rank
 FROM employees WHERE salary IS NOT NULL
)
SELECT MAX(CASE WHEN salary_rank=2 THEN salary END) AS second_salary FROM r;

WITH r AS (
 SELECT *, DENSE_RANK() OVER (PARTITION BY dept ORDER BY salary DESC) AS salary_rank
 FROM employees WHERE salary IS NOT NULL
)
SELECT dept, employee_id, salary FROM r WHERE salary_rank<=2
ORDER BY dept, salary DESC, employee_id;

WITH r AS (
 SELECT *, ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC, employee_id) AS rn
 FROM employees WHERE salary IS NOT NULL
)
SELECT dept, employee_id FROM r WHERE rn=1 ORDER BY dept;

WITH r AS (
 SELECT *, ROW_NUMBER() OVER (
 PARTITION BY event_id ORDER BY updated_at DESC, version_id DESC) AS rn
 FROM versions
)
SELECT event_id, version_id, status FROM r WHERE rn=1 ORDER BY event_id;

SELECT day, revenue,
 SUM(revenue) OVER (ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total
FROM daily ORDER BY day;

SELECT day, revenue,
 revenue - LAG(revenue) OVER (ORDER BY day) AS change_from_previous
FROM daily ORDER BY day;

SELECT customer_id, order_id,
 LEAD(order_id) OVER (PARTITION BY customer_id ORDER BY ordered_at, order_id) AS next_order_id
FROM date_orders ORDER BY customer_id, ordered_at, order_id;

WITH d AS (
 SELECT dept, SUM(salary) AS total_salary FROM employees GROUP BY dept
)
SELECT dept, total_salary,
 ROUND(100.0*total_salary/NULLIF(SUM(total_salary) OVER (),0),2) AS pct_of_total
FROM d ORDER BY dept;

WITH r AS (
 SELECT score, ROW_NUMBER() OVER (ORDER BY score, id) AS rn,
 COUNT(*) OVER () AS n FROM scores
)
SELECT AVG(score) AS median_score FROM r
WHERE rn IN (FLOOR((n+1)/2), FLOOR((n+2)/2));

SELECT order_id FROM date_orders
WHERE ordered_at >= '2024-03-03' AND ordered_at < '2024-03-04'
ORDER BY order_id;

SELECT id, DATEDIFF(ended_at,started_at) AS calendar_days,
 TIMESTAMPDIFF(HOUR,started_at,ended_at) AS full_hours
FROM durations ORDER BY id;

SELECT DATE_FORMAT(ordered_at,'%Y-%m') AS month_key, SUM(amount) AS revenue
FROM date_orders GROUP BY DATE_FORMAT(ordered_at,'%Y-%m')
ORDER BY month_key;

SELECT day, DATE_SUB(day, INTERVAL WEEKDAY(day) DAY) AS monday_start,
 YEARWEEK(day,3) AS iso_yearweek
FROM week_dates ORDER BY day;

WITH RECURSIVE calendar AS (
 SELECT CAST('2026-01-01' AS DATE) AS day
 UNION ALL SELECT DATE_ADD(day, INTERVAL 1 DAY) FROM calendar WHERE day<'2026-01-08'
), daily AS (
 SELECT day, SUM(amount) AS revenue FROM sales_days GROUP BY day
), filled AS (
 SELECT c.day, COALESCE(d.revenue,0) AS revenue
 FROM calendar c LEFT JOIN daily d ON d.day=c.day
)
SELECT day,revenue FROM filled ORDER BY day;

WITH RECURSIVE calendar AS (
 SELECT CAST('2026-01-01' AS DATE) AS day
 UNION ALL SELECT DATE_ADD(day, INTERVAL 1 DAY) FROM calendar WHERE day<'2026-01-08'
), daily AS (
 SELECT day, SUM(amount) AS revenue FROM sales_days GROUP BY day
), filled AS (
 SELECT c.day, COALESCE(d.revenue,0) AS revenue
 FROM calendar c LEFT JOIN daily d ON d.day=c.day
),
rolled AS (
 SELECT day, SUM(revenue) OVER (
 ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS rolling_7d FROM filled
)
SELECT day,rolling_7d FROM rolled
WHERE day>='2026-01-07' ORDER BY day;

WITH p AS (
 SELECT *,LAG(revenue) OVER (ORDER BY month_start) AS previous_revenue FROM monthly
)
SELECT month_start,revenue,previous_revenue,
 ROUND(100.0*(revenue-previous_revenue)/NULLIF(previous_revenue,0),2) AS growth_pct
FROM p ORDER BY month_start;

WITH prior AS (
 SELECT *,MAX(end_at) OVER (ORDER BY start_at,end_at,id
 ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS previous_max_end
 FROM intervals
), flags AS (
 SELECT *,CASE WHEN previous_max_end IS NULL OR start_at>=previous_max_end
 THEN 1 ELSE 0 END AS new_group FROM prior
), grouped AS (
 SELECT *,SUM(new_group) OVER (ORDER BY start_at,end_at,id
 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS grp FROM flags
)
SELECT MIN(start_at) AS merged_start,MAX(end_at) AS merged_end
FROM grouped GROUP BY grp ORDER BY merged_start;

WITH v AS (
 SELECT user_id,MIN(event_at) AS view_at FROM events WHERE kind='view' GROUP BY user_id
), c AS (
 SELECT v.user_id,v.view_at,MIN(e.event_at) AS cart_at FROM v
 JOIN events e ON e.user_id=v.user_id AND e.kind='cart' AND e.event_at>v.view_at
 GROUP BY v.user_id,v.view_at
), p AS (
 SELECT c.user_id,c.view_at,c.cart_at,MIN(e.event_at) AS purchase_at FROM c
 JOIN events e ON e.user_id=c.user_id AND e.kind='purchase' AND e.event_at>c.cart_at
 GROUP BY c.user_id,c.view_at,c.cart_at
)
SELECT user_id,view_at,cart_at,purchase_at FROM p ORDER BY user_id;

WITH p AS (
 SELECT order_id,SUM(amount) AS payment_total FROM payments GROUP BY order_id
), keys_all AS (
 SELECT order_id FROM orders UNION SELECT order_id FROM p
)
SELECT k.order_id,COALESCE(o.amount,0) AS order_amount,
 COALESCE(p.payment_total,0) AS payment_total,
 COALESCE(o.amount,0)-COALESCE(p.payment_total,0) AS difference
FROM keys_all k LEFT JOIN orders o ON o.order_id=k.order_id
LEFT JOIN p ON p.order_id=k.order_id ORDER BY k.order_id;

WITH r AS (
 SELECT id,SUM(amount) OVER (ORDER BY id
 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total FROM balances
)
SELECT id,running_total FROM r WHERE running_total>=60 ORDER BY id LIMIT 1;
